import test from 'node:test';import assert from 'node:assert/strict';import {createRewardAudio} from './rewardAudio.js';
function fake(){const events=[];class Context{state='running';currentTime=0;destination={};async resume(){}async close(){events.push('close');}async decodeAudioData(){return {duration:4.486};}createGain(){return {connect(){},gain:{setValueAtTime(){},linearRampToValueAtTime(){}}};}createBufferSource(){return {connect(){},start(...args){events.push(args);},stop(){events.push('stop');}};}}return {Context,events};}
test('starting the next recording cancels an audio download that finishes late',async()=>{let release;const {Context,events}=fake();const player=createRewardAudio('test',{Context,fetcher:()=>new Promise(resolve=>{release=()=>resolve({ok:true,arrayBuffer:async()=>new ArrayBuffer(0)});})});const pending=player.play();player.stop();release();assert.equal(await pending,false);assert.deepEqual(events,[]);player.close();});
test('real sound excerpt lasts 2.8 seconds and can be stopped immediately',async()=>{const {Context,events}=fake();const player=createRewardAudio('test',{Context,fetcher:async()=>({ok:true,arrayBuffer:async()=>new ArrayBuffer(0)})});assert.equal(await player.play(),true);assert.deepEqual(events[0],[0,0,2.8]);player.stop();assert.equal(events[1],'stop');player.close();});
